     1|/**
     2| * IVX Completion Validator
     3| *
     4| * Prevents false completion claims by comparing user-requested outcomes
     5| * against actual execution evidence. The validator rejects VERIFIED
     6| * when:
     7| *   - The requested outcome was not tested
     8| *   - The diff is empty for a code task
     9| *   - Tests are unrelated to the defect
    10| *   - Only /health was checked
    11| *   - Only a deployment occurred
    12| *   - The production commit does not contain the change
    13| *   - The same old evidence is reused for a new task
    14| *   - Evidence timestamps predate the task
    15| *   - A job claims success with no measurable output
    16| *
    17| * Pure — no I/O, no AI, fully unit-testable.
    18| */
    19|
    20|export const IVX_COMPLETION_VALIDATOR_MARKER =
    21|  'ivx-completion-validator-2026-07-22';
    22|
    23|export type IVXValidationVerdict =
    24|  | 'VERIFIED'
    25|  | 'DEPLOYED_ONLY'
    26|  | 'HEALTH_ONLY'
    27|  | 'NOT_COMPLETED'
    28|  | 'PARTIAL'
    29|  | 'BLOCKED'
    30|  | 'FAILED'
    31|  | 'NO_CHANGE';
    32|
    33|export type IVXCompletionValidatorInput = {
    34|  /** The user's original request text. */
    35|  userRequest: string;
    36|  /** Acceptance criteria the owner defined (if any). */
    37|  acceptanceCriteria: string[];
    38|  /** Task type from the classifier. */
    39|  taskType: string;
    40|  /** Whether any files were changed. */
    41|  filesChanged: string[];
    42|  /** Whether tests were run and what the result was. */
    43|  testsRun: boolean;
    44|  testsPassed: boolean;
    45|  testNames: string[];
    46|  /** Whether a commit was created. */
    47|  commitSha: string | null;
    48|  /** Whether a deployment occurred. */
    49|  deployId: string | null;
    50|  /** Whether /health was checked and returned 200. */
    51|  healthOk: boolean;
    52|  /** Whether feature-specific verification was performed. */
    53|  featureVerificationOk: boolean | null;
    54|  /** Whether the production commit contains the change. */
    55|  productionCommitMatches: boolean;
    56|  /** Timestamp when the task started. */
    57|  taskStartedAt: number;
    58|  /** Timestamp of the earliest evidence (commit, test, deploy). */
    59|  earliestEvidenceAt: number | null;
    60|  /** Whether any prior task used the same commit + deployId. */
    61|  reusedEvidence: boolean;
    62|  /** Whether device/browser QA was performed. */
    63|  deviceQAPerformed: boolean;
    64|  /** Whether the requested behavior was explicitly tested. */
    65|  requestedBehaviorTested: boolean;
    66|};
    67|
    68|export type IVXCompletionValidatorResult = {
    69|  verdict: IVXValidationVerdict;
    70|  ok: boolean;
    71|  reasons: string[];
    72|  remainingWork: string[];
    73|};
    74|
    75|/**
    76| * Validate whether a task can honestly claim completion.
    77| * This is the final gate before IVX can announce success.
    78| */
    79|export function validateCompletion(
    80|  input: IVXCompletionValidatorInput,
    81|): IVXCompletionValidatorResult {
    82|  const reasons: string[] = [];
    83|  const remainingWork: string[] = [];
    84|
    85|  const isCodeTask =
    86|    input.taskType === 'CODE_FIX' ||
    87|    input.taskType === 'FEATURE' ||
    88|    input.taskType === 'UI_FIX';
    89|
    90|  const isConfigTask =
    91|    input.taskType === 'CONFIGURATION_FIX' ||
    92|    input.taskType === 'INFRASTRUCTURE_FIX';
    93|
    94|  // Rule 1: A code task with an empty diff cannot be VERIFIED.
    95|  if (isCodeTask && input.filesChanged.length === 0) {
    96|    reasons.push(
    97|      'The code diff is empty for a code task — no development occurred.',
    98|    );
    99|    remainingWork.push('Inspect the actual code, identify the root cause, and modify the correct files.');
   100|  }
   101|
   102|  // Rule 2: Only /health was checked — cannot be VERIFIED from health alone.
   103|  if (input.healthOk && !input.featureVerificationOk && input.filesChanged.length === 0) {
   104|    reasons.push(
   105|      'Only /health was checked — infrastructure health passed but feature verification was not performed.',
   106|    );
   107|    remainingWork.push('Test the exact requested behavior in production, not just /health.');
   108|  }
   109|
   110|  // Rule 3: Only a deployment occurred with no code change.
   111|  if (input.deployId && input.filesChanged.length === 0 && !input.featureVerificationOk) {
   112|    reasons.push(
   113|      'Only a deployment occurred with no code change — this is a redeploy, not a fix.',
   114|    );
   115|    remainingWork.push('Make the requested code change before deploying.');
   116|  }
   117|
   118|  // Rule 4: Tests are unrelated to the defect.
   119|  if (input.testsRun && input.testsPassed && !input.requestedBehaviorTested) {
   120|    reasons.push(
   121|      'Tests passed but were not related to the requested defect — test the actual requested behavior.',
   122|    );
   123|    remainingWork.push('Write or run a test that verifies the specific requested behavior.');
   124|  }
   125|
   126|  // Rule 5: The production commit does not contain the change.
   127|  if (input.commitSha && !input.productionCommitMatches) {
   128|    reasons.push(
   129|      'The production commit does not contain the change — the deployed code does not match.',
   130|    );
   131|    remainingWork.push('Deploy the exact commit that contains the fix.');
   132|  }
   133|
   134|  // Rule 6: The same old evidence is reused for a new task.
   135|  if (input.reusedEvidence) {
   136|    reasons.push(
   137|      'The same commit and deployment ID were reused from a prior task — this is not new work.',
   138|    );
   139|    remainingWork.push('Create a new commit with the requested change and deploy it.');
   140|  }
