   147|    reasons.push(
   148|      'Evidence timestamps predate the task — the evidence is from prior work, not this task.',
   149|    );
   150|    remainingWork.push('Generate fresh evidence (commit, tests, deploy) after the task started.');
   151|  }
   152|
   153|  // Rule 8: A job claims success with no measurable output.
   154|  if (
   155|    !input.commitSha &&
   156|    !input.deployId &&
   157|    !input.testsRun &&
   158|    input.filesChanged.length === 0
   159|  ) {
   160|    reasons.push(
